 compensate only predicted single-input static NOR hazards.
fn balance_static_events(netlist: &Netlist, compiled: &mut reda::compile::CompiledCircuit) {
    use reda::compile::{geometry, topology::GateKind};
    use reda::redstone::{simulator::position::Position, world::block::BlockKind};
    if netlist.inputs.len() > 6 { return; }
    let Ok(routes) = reda::compile::routing_stats::analyze(netlist, compiled) else { return; };
    let cost: HashMap<_,_> = routes.edges.iter().map(|e| (e.sink.clone(), (e.total().repeaters*2) as u64)).collect();
    let mut ordered = Vec::new();
    let mut known: std::collections::BTreeSet<_> = netlist.inputs.iter().cloned().collect();
    let mut pending: Vec<_> = netlist.gates.iter().enumerate().collect();
    while !pending.is_empty() {
        let before = pending.len();
        pending.retain(|&(index,gate)| {
            if !gate.inputs.iter().all(|n| known.contains(n)) { return true; }
            if !matches!(gate.kind, GateKind::Nor(_) | GateKind::Or(_)) { return true; }
            known.insert(gate.output.clone()); ordered.push((index,gate)); false
        });
        if pending.len()==before { return; }
    }
    let truth = |bits: usize| {
        let mut values: HashMap<String,bool> = netlist.inputs.iter().enumerate().map(|(i,n)| (n.clone(),bits&(1<<i)!=0)).collect();
        for &(_,gate) in &ordered {
            let any = gate.inputs.iter().any(|n| values[n]);
            values.insert(gate.output.clone(), if matches!(gate.kind,GateKind::Nor(_)) { !any } else { any });
        }
        values
    };
    let states: Vec<_> = (0..1usize<<netlist.inputs.len()).map(truth).collect();
    let mut additions = std::collections::BTreeMap::<(usize,usize),u64>::new();
    for from in 0..states.len() {
        for bit in 0..netlist.inputs.len() {
            let to = from^(1<<bit); let old=&states[from]; let new=&states[to];
            let mut arrival: HashMap<String,u64> = netlist.inputs.iter().map(|n| (n.clone(),0)).collect();
            for &(index,gate) in &ordered {
                let times: Vec<_> = gate.inputs.iter().enumerate().map(|(i,n)| arrival[n]+cost[&format!("{}.in[{}]",gate.output,i)]).collect();
                let rising: Vec<_> = gate.inputs.iter().enumerate().filter(|(_,n)| !old[*n] && new[*n]).map(|(i,_)| times[i]).collect();
                let falling: Vec<_> = gate.inputs.iter().enumerate().filter(|(_,n)| old[*n] && !new[*n]).map(|(i,_)| (i,times[i])).collect();
                if old[&gate.output] == !matches!(gate.kind,GateKind::Nor(_)) && new[&gate.output] == old[&gate.output]
                    && !gate.inputs.iter().any(|n| old[n] && new[n]) {
                    if let (Some(first_on),Some(last_off)) = (rising.iter().min(),falling.iter().map(|(_,t)| t).max()) {
                        if last_off < first_on {
                            // Delay an actual falling endpoint; never delay the replacement high.
                            let facing=compiled.gate_facings[index];
                            let (x,y,z)=compiled.gate_output_positions[&gate.output];
                            let output=Position::new(x,y,z);
                            let support=if matches!(gate.kind,GateKind::Nor(_)) {output.offset(geometry::output_direction(facing).opposite())} else {output};
                            for &(i,time) in &falling {
                                let socket=support.offset(geometry::input_directions(facing)[i]);
                                let state=compiled.world.get(socket.x,socket.y,socket.z);
                                if state.kind!=BlockKind::Repeater { continue; }
                                let extra=((*first_on-time).div_ceil(2)).min(4-state.delay as u64);
                                additions.entry((index,i)).and_modify(|x| *x=(*x).max(extra)).or_insert(extra);
                                break;
                            }
                        }
                    }
                }
                let is_nor=matches!(gate.kind,GateKind::Nor(_));
                let tick=if old[&gate.output]!=new[&gate.output] {
                    if new[&gate.output] != is_nor { rising.iter().copied().min().unwrap() }
                    else { falling.iter().map(|(_,t)| *t).max().unwrap() }
                } else { 0 };
                arrival.insert(gate.output.clone(),tick+if is_nor {2} else {0});
            }
        }
    }
    for (&(index,i),&extra) in &additions {
        let gate=&netlist.gates[index];let facing=compiled.gate_facings[index];
        let (x,y,z)=compiled.gate_output_positions[&gate.output];
        let output=Position::new(x,y,z);
                            let support=if matches!(gate.kind,GateKind::Nor(_)) {output.offset(geometry::output_direction(facing).opposite())} else {output};
        let socket=support.offset(geometry::input_directions(facing)[i]);
        let mut state=compiled.world.get(socket.x,socket.y,socket.z).clone();
        state.delay+=extra as u8;compiled.world.set(socket.x,socket.y,socket.z,state);
        eprintln!("event-balanced {} input {} by {} redstone ticks",gate.output,i,extra);
    }
    eprintln!("event-balanced endpoints: {}",additions.len());
}
